/* 技能分類標籤（0.2.42，照 poe2db，名詞在 TERMS）：加在每招原本的 tags 後面。沒列的技能（詛咒、印記、召喚、擲矛…）沒有新標籤。
   strike 打擊＝武器直接打中的近戰，slam 重擊＝有範圍效果（有 aoe 標籤）的近戰，兩者互斥；nova 以自己為中心的圓；
   duration 有 dur 可調；sustained 一段時間內大量擊中（每下各自暴擊）；remote 圖騰、陷阱、地雷、砲塔圖騰、幻影放的；
   repeat 一次出手就放完的投射物與法術；stack 使用時替你累積疊層；cond 要先達成條件（榮耀、屍體、滑鼠附近有敵人）；channel 引導：目前沒有技能 */
