/* 輔助的分類（0.2.9，照 PoE2 0.3）：同一分類不能插在同一顆技能上，可以跨技能重複；沒寫的分類就是自己（同一顆不能插兩次） */
const SUP_CAT = {
  scorch: 'alt',
  brittle: 'alt',
  sap: 'alt',
  cast_crit: 'meta',
  autocast: 'meta',
  cast_kill: 'meta',
  cast_dodge: 'meta',
  cast_block: 'meta',
  cast_hurt: 'meta',
  /* 迴旋會搶在連鎖前面（穿透用完就飛回來），同插連鎖等於白插 */
  ret: 'chain',
  focus: 'area'
};
/* 自動化：附加的冷卻、魔力倍率 */
const AUTO = { cd: 8, mp: 1.4 };
const supCat = k => SUP_CAT[k] || k;
/* 輔助分級（0.2.51，企劃書 6.5）：II 是另一顆寶石，鍵＝I 的鍵＋'2'；跟 I 同分類（不能同插）、同圖示。
   這裡只放 II 的說明文字，數字在 skills.js 的 gemCfg 用 t2 分開寫；沒列在這裡的輔助不分級 */
/* II 版本（0.2.51）：說明與詳細（2026-11-11 照 PoE2 重寫） */
const SUP_II = {
  multi: {
    d: '輔助投射物技能，使其發射更多投射物，代價是造成更少傷害。',
    x: ['被輔助的技能投射物 +2', '被輔助的技能造成 10%更少傷害']
  },
  pierce: { d: '輔助投射物技能，使其投射物穿透更多敵人。', x: ['被輔助的技能投射物額外穿透 5 個敵人'] },
  area: { d: '輔助範圍或近戰技能，使其範圍更大。', x: ['被輔助的技能 55%更多範圍'] },
  fury: {
    d: '輔助任何技能，使其造成更多傷害，代價是消耗更多魔力。',
    x: ['被輔助的技能造成 45%更多傷害', '被輔助的技能 50%更多魔力消耗']
  },
  haste: { d: '輔助攻擊或法術技能，使其使用得更快。', x: ['被輔助的技能 32%更多技能速度'] },
  crit: {
    d: '輔助任何會擊中敵人的技能，使其更容易暴擊、暴擊更痛。',
    x: ['被輔助的技能增加 70% 暴擊率', '被輔助的技能暴擊傷害加成 +50%']
  },
  heavy: {
    d: '輔助近戰技能，使其擊退更遠、造成更多傷害與沉重暈眩累積。',
    x: ['被輔助的技能擊退距離加倍', '被輔助的技能造成 22%更多傷害', '被輔助的技能 70%更多沉重暈眩累積']
  },
  leech: { d: '輔助任何會擊中敵人的技能，使其擊中時偷取生命。', x: ['被輔助的技能擊中傷害的 4% 偷取為生命'] },
  cdr: { d: '輔助有冷卻時間的技能，使其冷卻時間恢復更快。', x: ['被輔助的技能增加 65% 冷卻時間恢復率'] },
  fireadd: {
    d: '輔助任何會造成傷害的技能，使其獲得額外火焰傷害。',
    x: ['被輔助的技能獲得等同於 32% 傷害的額外火焰傷害']
  },
  coldadd: {
    d: '輔助任何會造成傷害的技能，使其獲得額外冰冷傷害。',
    x: ['被輔助的技能獲得等同於 32% 傷害的額外冰冷傷害']
  },
  lightadd: {
    d: '輔助任何會造成傷害的技能，使其獲得額外閃電傷害。',
    x: ['被輔助的技能獲得等同於 32% 傷害的額外閃電傷害']
  },
  chaosadd: {
    d: '輔助任何會造成傷害的技能，使其獲得額外混沌傷害。',
    x: ['被輔助的技能獲得等同於 32% 傷害的額外混沌傷害']
  }
};
for (const k in SUP_II) {
  SUPPORTS[k + '2'] = { ...SUPPORTS[k], n: SUPPORTS[k].n + ' II', ...SUP_II[k], base: k, tier: 2 };
  SUP_CAT[k + '2'] = supCat(k);
}
/* 覺醒輔助（0.2.80，企劃書 4.2「四凶」，照 PoE1）：先做 8 顆，鍵＝'aw_'＋原版的鍵，跟原版、II 同分類（不能同插）。
   只從四凶掉：沒有就解鎖（S.lib.sup 有記錄才算有）、再撿到 +1 級（不能花靈魂升），上限 Lv5，燭龍之心突破到 Lv6。
   v(lv) 回傳這一級的數字（skills.js 的 gemCfg 讀），Lv5 起插的技能等級 +1、Lv6 +2；d(v) 是說明 */
const AW_LV = lv => Math.min(1, (lv - 1) / 4) + (lv > 5 ? 0.5 : 0); /* Lv1 → 0、Lv5 → 1、Lv6 → 1.5 */
const AW_SUP = {
  multi: { d: v => `投射物 +${v.proj}，傷害更少 5%`, v: lv => ({ proj: lv >= 5 ? 3 : 2 }) },
  area: {
    d: v => `範圍 +${v.aoe}%${v.more ? `、範圍傷害更多 ${v.more}%` : ''}`,
    v: lv => ({ aoe: Math.round(60 + 10 * AW_LV(lv)), more: lv >= 5 ? 10 : 0 })
  },
  fury: { d: v => `傷害更多 ${v.more}%，魔力消耗 ×1.5`, v: lv => ({ more: Math.round(50 + 10 * AW_LV(lv)) }) },
  haste: { d: v => `出手速度更快 ${v.spd}%`, v: lv => ({ spd: Math.round(35 + 5 * AW_LV(lv)) }) },
  crit: {
    d: v => `暴擊率提高 ${v.ci}%、暴擊傷害加成 +${v.cx}%`,
    v: lv => ({ ci: Math.round(80 + 10 * AW_LV(lv)), cx: Math.round(55 + 10 * AW_LV(lv)) })
  },
  chain: {
    d: v => `投射物多彈 3 隻${v.less > 0 ? `；傷害更少 ${v.less}%` : '，不減傷'}`,
    v: lv => ({ less: Math.max(0, Math.round(10 * (1 - AW_LV(lv)))) })
  },
  elepen: { d: v => `這招的擊中穿透敵人 ${v.pen}% 抗性`, v: lv => ({ pen: Math.round(30 + 5 * AW_LV(lv)) }) },
  ailmag: { d: v => `異常強度提高 ${v.ail}%`, v: lv => ({ ail: Math.round(40 + 10 * AW_LV(lv)) }) }
};
const AW_MAX = 5;
const awSupText = (k, lv) => {
  const b = SUPPORTS[k].base;
  return AW_SUP[b].d(AW_SUP[b].v(lv)) + (lv >= 6 ? '；插的技能等級 +2' : lv >= 5 ? '；插的技能等級 +1' : '');
};
/* 覺醒輔助的說明（2026-11-11）；數字在 x，由 awSupText 產生 */
const AW_D = {
  multi: '輔助投射物技能，使其發射更多投射物，但造成更少傷害。',
  area: '輔助範圍或近戰技能，使其範圍更大；高等級時傷害也更高。',
  fury: '輔助任何技能，使其造成更多傷害，代價是消耗更多魔力。',
  haste: '輔助攻擊或法術技能，使其使用得更快。',
  crit: '輔助任何會擊中敵人的技能，使其更容易暴擊、暴擊更痛。',
  chain: '輔助投射物技能，使其投射物連鎖更多次；高等級時不再減少傷害。',
  elepen: '輔助任何會擊中敵人的技能，使其擊中穿透敵人的抗性。',
  ailmag: '輔助任何會擊中敵人的技能，使其異常狀態更強。'
};
for (const k in AW_SUP) {
  SUPPORTS['aw_' + k] = { ...SUPPORTS[k], n: '覺醒・' + SUPPORTS[k].n, base: k, aw: 1, d: '' };
  SUPPORTS['aw_' + k].d = AW_D[k];
  SUPPORTS['aw_' + k].x = [awSupText('aw_' + k, 1), 'Lv5：' + awSupText('aw_' + k, 5)];
  SUP_CAT['aw_' + k] = supCat(k);
}
/* 寶石等級：上限 20；每一級要的角色等級照 PoE2（0.2.40；Lv5 要 14、Lv20 要 90），超過 20 級（裝備加等級、腐化）不再要求 */
const GEM_MAX = 20;
/* 覺醒（0.2.75，企劃書 6.3）：AWK[技能鍵] = { A: { n, d }, B?: { n, fx, tags? } }。A＝原版增強：這招傷害更多 15%（有傷害的招）＋原本 0.2.29 品質 20% 的效果（gemCfg 的 c.q）；
   B＝變化版：fx 是 gemCfg 最後套的補丁（more／aoe／speed／kb／mp／cd 相乘，proj／pierce／chain／critInc／ailMag／bleedCh／volley 相加），tags 改標籤（輔助相容性跟著變）。
   第一批只有綁武器的 48 招（加隕石一招給 dmg_check 對照）有 B，法系的留 0.2.76；沒有 B 的招覺醒時只有 A 一張卡 */
const AW_MORE = 1.15;
/* B 的補丁寫成中文（說明文字由資料組出來，不手寫）：m＝倍率換成 ±%，a＝加幾 */
const FXC = (bad, t) => (bad ? `\uE000${t}\uE001` : t); /* 代價用私用字元框起來，skpanel.js 的 rich() 換成橘色 .cost */
const FXN = {
  more: m => (m >= 1 ? `${Math.round((m - 1) * 100)}%更多傷害` : FXC(1, `${Math.round((1 - m) * 100)}%更少傷害`)),
  aoe: m => FXC(m < 1, `${Math.abs(Math.round((m - 1) * 100))}%${m >= 1 ? '更多' : '更少'}範圍效果`),
  speed: m => FXC(m < 1, `${Math.abs(Math.round((m - 1) * 100))}%${m >= 1 ? '更多' : '更少'}技能速度`),
  cd: m => FXC(m > 1, `冷卻時間${m >= 1 ? '延長' : '縮短'} ${Math.abs(Math.round((m - 1) * 100))}%`),
  mp: m => FXC(m > 1, `${Math.abs(Math.round((m - 1) * 100))}%${m >= 1 ? '更多' : '更少'}魔力消耗`),
  kb: m => `${Math.abs(Math.round((m - 1) * 100))}%${m >= 1 ? '更多' : '更少'}擊退距離`,
  proj: a => `投射物 +${a}`,
  pierce: a => `額外穿透 ${a} 個目標`,
  chain: a => `額外連鎖 ${a} 次`,
  critInc: a => `增加 ${a}% 暴擊率`,
  ailMag: a => `增加 ${a}% 異常強度`,
  bleedCh: a => `+${a}% 流血機率`,
  volley: a => `同時落下 ${a} 顆隕石`
};
const fxText = fx =>
  Object.keys(fx)
    .map(k => FXN[k](fx[k]))
    .join('、');
