/* chg：一瓶等於幾點 PoE2 的充能（每次使用 10 充能，滿溢聖杯換算用） */
/* 0.3.1：紅水藍水不限次數、各自 3 秒冷卻（cd，P.cds.flask／mflask）；充能 n 只剩藥劑技能（追獵者）在用 */
